const agent = $input.first().json;
const unwrap = (value) => {
  let current = value;
  for (let depth = 0; depth < 3; depth += 1) {
    if (typeof current === 'string') {
      try { current = JSON.parse(current); continue; } catch { return null; }
    }
    if (Array.isArray(current)) { current = current.at(-1); continue; }
    if (current && typeof current === 'object' && current.json && typeof current.json === 'object') {
      current = current.json;
      continue;
    }
    break;
  }
  return current && typeof current === 'object' ? current : null;
};

let preview = {};
const steps = Array.isArray(agent.intermediateSteps) ? [...agent.intermediateSteps].reverse() : [];
for (const step of steps) {
  const candidate = unwrap(step?.observation);
  if (candidate?.proposal) { preview = candidate; break; }
}
if (!preview.proposal) {
  try {
    const previewItems = $('Preview AI Page Changes').all();
    preview = previewItems.at(-1)?.json || {};
  } catch {}
}

const proposal = preview.proposal && typeof preview.proposal === 'object' ? preview.proposal : null;
const previewToken = typeof proposal?.previewToken === 'string' ? proposal.previewToken : '';
const changes = Array.isArray(proposal?.changes) ? proposal.changes.map((item) => String(item)).filter(Boolean) : [];
const agentOutput = String(agent.output || '').trim();
const reply = String(preview.reply || agentOutput).trim();
const summary = String(proposal?.summary || '').trim();
const expectedRevision = Number(proposal?.expectedRevision);
const expiresAt = String(proposal?.expiresAt || '').trim();
const proposalLines = [
  reply,
  '',
  '## OrbitPage preview',
  ...(summary ? [`**Summary:** ${summary}`] : []),
  ...(changes.length ? ['', '**Changes:**', ...changes.map((change) => `- ${change}`)] : []),
  ...(Number.isSafeInteger(expectedRevision) ? ['', `**Reviewed draft revision:** ${expectedRevision}`] : []),
  ...(expiresAt ? [`**Expires:** ${expiresAt}`] : []),
  '',
  '**Nothing has changed yet.** Review the proposal above, then use the buttons below.'
].filter((line, index, list) => line !== '' || list[index - 1] !== '');
const chatResponse = previewToken
  ? proposalLines.join('\n')
  : agentOutput || 'I could not produce a response. Please retry the request.';
return [{ json: { chatResponse, hasPreview: Boolean(previewToken), previewToken } }];

const applied = $('Apply Approved Preview').first().json;
const publicationResponse = $input.first().json;
const publication = publicationResponse.data || publicationResponse;
if (applied.error) {
  return [{ json: { chatResponse: `The preview was not published. OrbitPage returned: ${String(applied.error)}` } }];
}
const revision = Number(applied.revision ?? publication.publishedRevision ?? publication.revision);
const status = String(applied.publication || publication.status || publication.publicationStatus || 'unknown');
const publicUrl = String(publication.publicUrl || '').trim();
const details = [
  Number.isSafeInteger(revision) ? `Revision: ${revision}` : '',
  `Publication status: ${status}`,
  publicUrl ? `Public page: ${publicUrl}` : ''
].filter(Boolean);
return [{ json: { chatResponse: `The approved OrbitPage preview was applied.\n\n${details.join('\n')}` } }];
